@RestController
public class OrderController {

    private final OrderRepository orderRepository;

    public OrderController(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    // Using Virtual Threads with classic blocking style instead of WebFlux Mono/Flux
    @GetMapping("/orders/{id}")
    public Order getOrder(@PathVariable Long id) {
        // This call blocks the virtual thread, but NOT an OS carrier thread.
        // The JVM automatically unmounts the virtual thread during IO.
        return orderRepository.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }
}
